mapper.select:
SELECT
	r.id AS review_id,
	r.place_id,
	re.embedding,
	r.created_at
FROM reviews r
JOIN review_embeddings re ON re.review_id = r.id
WHERE r.user_id <> #{userId}
  AND re.embedder_version = #{embedderVersion}

  AND r.created_at <= #{asOf}

  AND NOT EXISTS (
	SELECT 1
	FROM likes l
	WHERE l.user_id = #{userId}
	  AND l.review_id = r.id

	  AND l.created_at <= #{asOf}

  )

  AND NOT EXISTS (
	SELECT 1
	FROM review_impressions ri
	WHERE ri.user_id = #{userId}
	  AND ri.review_id = r.id
	  AND ri.last_seen_at >= #{seenSince}

	  AND ri.last_seen_at <= #{asOf}

  )

ORDER BY r.created_at DESC, r.id DESC
LIMIT #{limit}
